#!/usr/bin/env python3
"""Compute compact numeric ground truth for CSX-083_Q1."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-083_Q1"
EVENT_ID = "CSX-083"
ROOT = Path(__file__).resolve().parents[3]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

REPORT_FILE = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
POINT_DAILY_FILE = "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json"
ANCHOR_FILE = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_Typhoon_Doksuri_Beijing-Tianjin-Hebei_and_Haihe_flood.json"
)
THRESHOLD_RATIO = 3.0


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._active = False
        self._current: list[str] = []
        self.blocks: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "meta":
            content = dict(attrs).get("content")
            if content:
                self.blocks.append(content)
        if tag in {"p", "li", "h1", "h2", "h3"}:
            self._active = True
            self._current = []

    def handle_endtag(self, tag: str) -> None:
        if self._active and tag in {"p", "li", "h1", "h2", "h3"}:
            text = " ".join("".join(self._current).split())
            if text:
                self.blocks.append(text)
            self._active = False

    def handle_data(self, data: str) -> None:
        if self._active:
            self._current.append(data)


def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE / rel_path).read_text(encoding="utf-8-sig"))


def report_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((PACKAGE / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parser.blocks)


def require(pattern: str, text: str, flags: int = re.IGNORECASE) -> re.Match[str]:
    match = re.search(pattern, text, flags)
    if not match:
        raise RuntimeError(f"Missing required report pattern: {pattern}")
    return match


def main() -> None:
    text = report_text(REPORT_FILE)
    anchor = read_json(ANCHOR_FILE)
    daily = read_json(POINT_DAILY_FILE)["properties"]["parameter"]["PRECTOTCORR"]

    reported_total = float(require(r"logged ([0-9.]+) millimeters of rain", text).group(1))
    point_values = [float(value) for value in daily.values()]
    point_total = round(sum(point_values), 2)
    ratio = round(reported_total / point_total, 2)

    if not (
        anchor["locked_event_anchor"]["event_lock_notes"].startswith("Doksuri remnants")
        and reported_total == 744.8
        and point_total == 220.61
    ):
        raise RuntimeError("CSX-083 source values did not match expected event anchors")

    concentration_class = (
        "spatially concentrated extreme local maximum"
        if ratio >= THRESHOLD_RATIO
        else "comparable to the point-window total"
    )
    structured_answer = {
        "reported_storm_total_mm": reported_total,
        "point_event_total_mm": point_total,
        "reported_to_point_ratio": ratio,
        "concentration_class": concentration_class,
        "computed_interpretation": (
            "The reported local maximum is more than three times the nearby point-window total, "
            "so it should be treated as a focused storm maximum rather than an ordinary "
            "wet-period accumulation."
        ),
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L2",
        "primary_gt": {
            "answer": "ratio_3.38_extreme_local_maximum",
            "structured_answer": structured_answer,
            "decision_threshold_ratio": THRESHOLD_RATIO,
            "tolerances": {
                "reported_storm_total_mm": 0.1,
                "point_event_total_mm": 0.01,
                "reported_to_point_ratio": 0.02,
            },
        },
        "key_values": {
            "event_window": "2023-07-29 to 2023-08-02",
            "daily_point_rainfall_mm": point_values,
            "reported_storm_total_mm": reported_total,
            "point_event_total_mm": point_total,
            "reported_to_point_ratio": ratio,
            "threshold_ratio": THRESHOLD_RATIO,
            "concentration_class": concentration_class,
        },
        "decision_rule": "Classify as a spatially concentrated extreme local maximum when reported_to_point_ratio >= 3.0.",
        "accepted_answer_formats": [
            "A compact JSON object using the visible field names.",
            "Numeric values may be numbers or numeric strings with millimeter units.",
            "The ratio may be 3.38, about 3.4x, or another value within tolerance.",
        ],
        "out_of_scope_statements": [
            "Do not convert the rainfall ratio into exact loss totals.",
            "Do not treat the point total as the event-wide maximum rainfall amount.",
            "Do not describe the reported total as comparable to the point-window total.",
        ],
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Reported storm rainfall total",
                    "points": 4,
                    "description": "Reports reported_storm_total_mm as 744.8 mm within 0.1 mm and identifies it as the reported local storm total.",
                    "partial_credit": "Gives a nearby value or the right number without clear units or role.",
                },
                {
                    "name": "Point event-window rainfall total",
                    "points": 4,
                    "description": "Sums the five daily point rainfall values to 220.61 mm within 0.01 mm.",
                    "partial_credit": "Uses most daily values correctly with a minor arithmetic or rounding error.",
                },
                {
                    "name": "Rainfall concentration ratio",
                    "points": 4,
                    "description": "Computes reported_to_point_ratio as 3.38 within 0.02, or an equivalent about-3.4x comparison.",
                    "partial_credit": "Uses the correct numerator and denominator with modest rounding error.",
                },
                {
                    "name": "Threshold classification",
                    "points": 3,
                    "description": "Applies the 3.0 decision rule and labels the result as a spatially concentrated extreme local maximum.",
                    "partial_credit": "States that the reported total is much larger but omits the threshold test.",
                },
                {
                    "name": "Local maximum versus point sum",
                    "points": 2,
                    "description": "Keeps the reported storm maximum separate from the point rainfall sum and does not treat either as a basinwide mean.",
                    "partial_credit": "Has a minor wording issue that does not change the arithmetic.",
                },
                {
                    "name": "Computed interpretation",
                    "points": 2,
                    "description": "Gives a concise interpretation tied directly to the ratio and the Doksuri-remnant flood episode.",
                    "partial_credit": "Gives a generic extreme-rainfall sentence that does not clearly use the ratio.",
                },
                {
                    "name": "Structured output clarity",
                    "points": 1,
                    "description": "Returns the requested compact JSON-like object with clear units.",
                    "partial_credit": "Mostly follows the fields with minor formatting or unit omissions.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [REPORT_FILE, POINT_DAILY_FILE, ANCHOR_FILE],
        },
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
